use strict; use warnings;
my $CPP="/workspace/dataset/test11_executable";
my $RS="/output/test11";
our $N=0; our @DIFF=(); our @CONTRA=(); our @NOISO=();

sub runx {
  my ($exe,@args)=@_;
  my $pid=open(my $fh, "-|");
  die "fork" unless defined $pid;
  if ($pid==0) { open(STDERR,'>','/dev/null'); exec($exe,@args) or exit 127; }
  local $/; my $out=<$fh>; $out='' unless defined $out;
  close($fh); my $rc=$?>>8;
  return ($out,$rc);
}

sub iso_f2 {
  my ($out,$s)=@_;
  my $off=4+length($s);
  return undef unless length($out)>$off && substr($out,$off,1) eq ' ';
  my $rest=substr($out,$off+1);
  for my $L (length($s)-4, length($s)) {
    next if $L<0;
    next unless length($rest)>$L && substr($rest,$L,1) eq ' ';
    my $f3="xn--".$s;
    next unless substr($rest,$L+1,length($f3)) eq $f3;
    next unless substr($rest,$L+1+length($f3),1) eq ' ';
    return substr($rest,0,$L);
  }
  return undef;
}
sub expect { my $s=shift; return (substr($s,0,4) eq 'xn--') ? substr($s,4) : $s; }
sub esc { my $x=shift; $x=~s/([^\x20-\x7e])/sprintf("\\x%02x",ord($1))/ge; return $x; }

sub probe {
  my (@args)=@_;
  $N++;
  my ($o1,$r1)=runx($CPP,@args);
  my ($o2,$r2)=runx($RS,@args);
  if ($o1 ne $o2 || $r1 != $r2) {
    push @DIFF, [join("\x1f",map{esc($_)}@args), esc($o1), esc($o2), $r1, $r2];
  }
  if (@args==1) {
    my $f2=iso_f2($o1,$args[0]);
    if (!defined $f2) { push @NOISO, [esc($args[0]), esc($o1)]; }
    elsif ($f2 ne expect($args[0])) { push @CONTRA, [esc($args[0]), esc($f2), esc(expect($args[0]))]; }
  }
  return ($o1,$o2,$r1,$r2);
}
sub report {
  print "PROBES: $N\n";
  print "BYTE-DIFFS: ".scalar(@DIFF)."\n";
  for my $d (@DIFF[0..($#DIFF>29?29:$#DIFF)]) { print "  DIFF args=[$d->[0]] rc=$d->[3]/$d->[4]\n    cpp=$d->[1]\n    rst=$d->[2]\n"; }
  print "CONTRACT-VIOLATIONS: ".scalar(@CONTRA)."\n";
  for my $d (@CONTRA[0..($#CONTRA>29?29:$#CONTRA)]) { print "  CONTRA in=[$d->[0]] got=[$d->[1]] want=[$d->[2]]\n"; }
  print "NO-ISOLATE: ".scalar(@NOISO)."\n";
  for my $d (@NOISO[0..($#NOISO>9?9:$#NOISO)]) { print "  NOISO in=[$d->[0]] out=[$d->[1]]\n"; }
}
1;
